sketch:
// Slide potentiometer — the divider of the knob, moved sideways.
//
// Slide the Position slider (or drag the tip on the canvas) while the sketch
// runs: A0 reads value/100 of the supply, the same divider as the rotary knob.
void setup() {
  Serial.begin(9600);
}

void loop() {
  Serial.print("A0 = ");
  Serial.println(analogRead(A0));
  delay(200);
}
